<?php require_once __DIR__.'/../config/config.php';require_post();$d=json_decode(file_get_contents('php://input'),true)?:$_POST;$name=trim((string)($d['name']??''));$phone=trim((string)($d['phone']??''));$date=trim((string)($d['date']??''));$departmentId=(int)($d['department_id']??0);$departmentName=trim((string)($d['department']??''));$time=trim((string)($d['time']??''));$reason=trim((string)($d['reason']??''));if($name===''||$phone===''||$date==='')json_response(['success'=>false,'message'=>'Name, phone and date are required.'],422);$dt=DateTime::createFromFormat('Y-m-d',$date);if(!$dt||$dt->format('Y-m-d')!==$date||$date<date('Y-m-d'))json_response(['success'=>false,'message'=>'Choose a valid future date.'],422);$pdo=db();$pdo->beginTransaction();try{$s=$pdo->prepare('SELECT id FROM patients WHERE phone=? AND full_name=? LIMIT 1');$s->execute([$phone,$name]);$p=$s->fetch();if(!$p){$no='PT-'.date('ym').'-'.strtoupper(bin2hex(random_bytes(3)));$s=$pdo->prepare('INSERT INTO patients(patient_no,full_name,phone,gender) VALUES(?,?,?,"Unknown")');$s->execute([$no,$name,$phone]);$pid=(int)$pdo->lastInsertId();}else{$pid=(int)$p['id'];}$departmentId=$departmentId?:0;if(!$departmentId&&$departmentName!==''){ $ds=$pdo->prepare('SELECT id FROM departments WHERE name LIKE ? LIMIT 1');$ds->execute(['%'.$departmentName.'%']);$departmentId=(int)($ds->fetchColumn()?:0); }$s=$pdo->prepare('INSERT INTO appointments(patient_id,patient_name,phone,department_id,appointment_date,appointment_time,reason) VALUES(?,?,?,?,?,?,?)');$s->execute([$pid,$name,$phone,$departmentId?:null,$date,$time?:null,$reason]);$aid=(int)$pdo->lastInsertId();$pdo->commit();json_response(['success'=>true,'appointment_id'=>$aid,'message'=>'Appointment request received.']);}catch(Throwable $e){$pdo->rollBack();json_response(['success'=>false,'message'=>'Unable to save appointment.'],500);}
